def run():
    cs=read(C/'SUMMARY.json');ss=read(S/'SUMMARY.json');rows=read(S/'ROWS.json');raw=[load(f) for f in (S/'online').rglob('*.pt')];updates=[x for x in raw if x['updated']];center_changed=0;centers=0;rank_changes=0
    oldcrit={(r['parent'],r['condition']):r for r in read(C/'REWARDS.json')}
