    vals=lambda key:[x['update'][key] for x in updates]
    qrange=[float(x['update']['q'].max()-x['update']['q'].min()) for x in updates];prange=[float(x['update']['p'].max()-x['update']['p'].min()) for x in updates]
    resource=dict(gpu_process_seconds=sum(read(f)['seconds'] for f in (S/'allocations').glob('*.json')),new_expert_calls=0,new_backbone_captures=0,scheduled_expert_arrivals=24,valid_updates=len(updates),backward_calls=len(updates),regenerated_candidate_sets=centers,regenerated_candidate_tubes=9*centers,learned_center_sets=center_changed,current_reward_argmax_changed_vs_source=rank_changes)
    diag=dict(loss_decreased=sum(x['update']['loss_after']<x['update']['loss_before'] for x in updates),gradient_norm=stats(vals('gradient_norm')),query_gradient_nonzero=sum(x['update']['query_gradient_norm']>0 for x in updates),LN_gradient_nonzero=sum(x['update']['LN_gradient_norm']>0 for x in updates),step_norm=stats([x['parameter_displacement'] for x in updates]),teacher_probability_range=stats(qrange),student_probability_range=stats(prange),step_to_probe_ratio=stats([x['parameter_displacement']/1.5765801926049214 for x in updates]),final_stream_norms={x['condition']:x['displacement_from_source'] for x in raw if x['arrival']==15},nonexpert_after_first_effective_update={})
